import csv

# Read the input CSV
rows = []
with open('outputs/t11_city_indicator_matrix.csv', 'r', encoding='utf-8') as f:
    reader = csv.reader(f)
    for row in reader:
        if not row or len(row) < 11:
            continue
        rows.append(row)

# Get header
header = rows[0]
header_fields = header

# Get indicator columns (skip city_id, city_name, year)
indicator_columns = header_fields[3:]

# Count missing values per indicator
missing_counts = {}
for row in rows[1:]:
    indicator_values = {}
    for i, field in enumerate(header_fields[3:], start=3):
        if field == '':
            indicator_values[field] = None
        else:
            indicator_values[field] = field

    for indicator in indicator_columns:
        if indicator not in indicator_values:
            continue

        # Count missing values
        missing_count = sum(1 for val in indicator_values[indicator] if val is None)
        missing_rate = missing_count / len(indicator_values[indicator]) if len(indicator_values[indicator]) > 0 else 0.0

        missing_counts[indicator] = {
            'missing_count': missing_count,
            'missing_rate': missing_rate,
            'kept': missing_rate <= 0.30
        }

# Write the missingness report
report_path = 'outputs/t12_missingness_report.csv'
with open(report_path, 'w', newline='', encoding='utf-8') as f:
    writer = csv.writer(f)
    writer.writerow(['indicator', 'missing_count', 'missing_rate', 'kept'])
    for indicator in sorted(missing_counts.keys()):
        data = missing_counts[indicator]
        writer.writerow([
            indicator,
            data['missing_count'],
            data['missing_rate'],
            '1' if data['kept'] else '0'
        ])

# Write the selected matrix
selected_path = 'outputs/t12_selected_matrix.csv'
with open(selected_path, 'w', newline='', encoding='utf-8') as f:
