    writer.writerow(['city_id', 'city_name', 'year', 'DE1001V', 'DE1002V', 'DE3001V', 'DE3017V', 'TT1003V', 'TT1006V', 'TT1007V', 'TT1010V'])
    for row in rows[1:]:
        indicator_values = {}
        for i, field in enumerate(header_fields[3:], start=3):
            if field == '':
                indicator_values[field] = None
            else:
                indicator_values[field] = field

        selected_row = []
        for indicator in indicator_columns:
            if indicator in missing_counts and missing_counts[indicator]['kept']:
                selected_row.append(indicator_values[indicator])

        writer.writerow([
            row[0],
            row[1],
            row[2],
            *selected_row
        ])

